            ["Modes"] = "Modos",
            ["Mouse"] = "Ratón",
            ["Mouse-cursor color tint (local-only). Pick the cursor SHAPE — arrow, dot, crosshair, circle — in Settings; the tint colors whichever shape you choose."] = "Tinte de color del cursor del ratón (solo local). Elige la FORMA del cursor — flecha, punto, mira, círculo — en Ajustes; el tinte colorea la forma que elijas.",
            ["Movement & shield tech"] = "Movimiento y tech de escudo",
            ["Music"] = "Música",
            ["Music credit toast: <color=#88FF88>ON</color>"] = "Aviso de crédito musical: <color=#88FF88>SÍ</color>",
            ["Music credit toast: <color=#FF9966>OFF</color>"] = "Aviso de crédito musical: <color=#FF9966>NO</color>",
            ["Music download failed - press Retry"] = "La descarga de música falló - pulsa Reintentar",
