            ["<color=#CCCCCC>Scoring history</color>  <color=#66DD66>{0}</color> <color=#888>vs</color> <color=#DD7777>opponent</color>"] = "<color=#CCCCCC>Historial de puntos</color>  <color=#66DD66>{0}</color> <color=#888>vs</color> <color=#DD7777>rival</color>",
